diff --git a/src/applet/deviceicons.cpp b/src/applet/deviceicons.cpp
new file mode 100644
index 00000000..97dae0dd
--- /dev/null
+++ b/src/applet/deviceicons.cpp
@@ -0,0 +1,71 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "deviceicons.h"
+
+#include <QCoreApplication>
+#include <QQmlEngine>
+
+DeviceIcons::DeviceIcons(QObject *parent)
+    : QObject(parent)
+    , m_config(KSharedConfig::openConfig(QStringLiteral("bluedevilglobalrc")))
+    , m_group(m_config, QStringLiteral("DeviceIcons"))
+    , m_watcher(KConfigWatcher::create(m_config))
+{
+    connect(m_watcher.data(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group) {
+        if (group.name() == m_group.name()) {
+            Q_EMIT iconsChanged();
+        }
+    });
+}
+
+DeviceIcons *DeviceIcons::instance()
+{
+    static DeviceIcons *s_instance = new DeviceIcons(qApp);
+    return s_instance;
+}
+
+DeviceIcons *DeviceIcons::create(QQmlEngine *engine, QJSEngine *scriptEngine)
+{
+    Q_UNUSED(engine)
+    Q_UNUSED(scriptEngine)
+
+    QQmlEngine::setObjectOwnership(instance(), QQmlEngine::CppOwnership);
+    return instance();
+}
+
+QVariantMap DeviceIcons::icons() const
+{
+    QVariantMap icons;
+    const QStringList addresses = m_group.keyList();
+    for (const QString &address : addresses) {
+        icons.insert(address, m_group.readEntry(address, QString()));
+    }
+    return icons;
+}
+
+QString DeviceIcons::icon(const QString &address) const
+{
+    return m_group.readEntry(address, QString());
+}
+
+void DeviceIcons::setIcon(const QString &address, const QString &icon)
+{
+    if (address.isEmpty() || icon == this->icon(address)) {
+        return;
+    }
+
+    if (icon.isEmpty()) {
+        m_group.deleteEntry(address, KConfig::Notify);
+    } else {
+        m_group.writeEntry(address, icon, KConfig::Notify);
+    }
+    m_group.sync();
+
+    Q_EMIT iconsChanged();
+}
+
+#include "moc_deviceicons.cpp"
diff --git a/src/applet/deviceicons.h b/src/applet/deviceicons.h
new file mode 100644
index 00000000..c37b3225
--- /dev/null
+++ b/src/applet/deviceicons.h
@@ -0,0 +1,46 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#pragma once
+
+#include <KConfigGroup>
+#include <KConfigWatcher>
+#include <KSharedConfig>
+
+#include <QObject>
+#include <QVariantMap>
+#include <qqmlregistration.h>
+
+class QQmlEngine;
+class QJSEngine;
+
+class DeviceIcons : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    QML_SINGLETON
+
+    Q_PROPERTY(QVariantMap icons READ icons NOTIFY iconsChanged FINAL)
+
+public:
+    static DeviceIcons *instance();
+    static DeviceIcons *create(QQmlEngine *engine, QJSEngine *scriptEngine);
+
+    QVariantMap icons() const;
+    QString icon(const QString &address) const;
+
+    Q_INVOKABLE void setIcon(const QString &address, const QString &icon);
+
+Q_SIGNALS:
+    void iconsChanged();
+
+private:
+    explicit DeviceIcons(QObject *parent = nullptr);
+
+    KSharedConfig::Ptr m_config;
+    KConfigGroup m_group;
+    KConfigWatcher::Ptr m_watcher;
+};
