 #include <KLocalizedString>
@@ -17,6 +18,12 @@ DevicesProxyModel::DevicesProxyModel(QObject *parent)
 {
     setDynamicSortFilter(true);
     sort(0, Qt::DescendingOrder);
+
+    connect(DeviceIcons::instance(), &DeviceIcons::iconsChanged, this, [this] {
+        if (rowCount() > 0) {
+            Q_EMIT dataChanged(index(0, 0), index(rowCount() - 1, 0), {BluezQt::DevicesModel::IconRole});
+        }
+    });
 }

 bool DevicesProxyModel::hideBlockedDevices() const
@@ -80,6 +87,14 @@ QVariant DevicesProxyModel::data(const QModelIndex &index, int role) const
         }
         return QSortFilterProxyModel::data(index, BluezQt::DevicesModel::NameRole);

+    case BluezQt::DevicesModel::IconRole: {
+        const QString icon = DeviceIcons::instance()->icon(QSortFilterProxyModel::data(index, BluezQt::DevicesModel::AddressRole).toString());
+        if (!icon.isEmpty()) {
+            return icon;
+        }
+        return QSortFilterProxyModel::data(index, role);
+    }
+
     default:
         return QSortFilterProxyModel::data(index, role);
     }
